package com.advancedxptracker;

/**
 * Represents the different OSRS account types with their hiscores API endpoints
 */
public enum AccountType
{
	NORMAL("Normal", "https://services.runescape.com/m=hiscore_oldschool/index_lite.json?player=", "normal_icon.png"),
	IRONMAN("Ironman", "https://services.runescape.com/m=hiscore_oldschool_ironman/index_lite.json?player=", "ironman_icon.png"),
	HARDCORE_IRONMAN("Hardcore Ironman", "https://services.runescape.com/m=hiscore_oldschool_hardcore_ironman/index_lite.json?player=", "hardcore_ironman_icon.png"),
	ULTIMATE_IRONMAN("Ultimate Ironman", "https://services.runescape.com/m=hiscore_oldschool_ultimate/index_lite.json?player=", "ultimate_ironman_icon.png");

	private final String displayName;
	private final String apiUrl;
	private final String iconFileName;

	AccountType(String displayName, String apiUrl, String iconFileName)
	{
		this.displayName = displayName;
		this.apiUrl = apiUrl;
		this.iconFileName = iconFileName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getApiUrl()
	{
		return apiUrl;
	}

	public String getIconFileName()
	{
		return iconFileName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.advancedxptracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * Configuration for Hiscores Tracker
 */
@ConfigGroup("advancedxptracker")
public interface AdvancedXpTrackerConfig extends Config
{
	@ConfigSection(
		name = "Refresh Settings",
		description = "Configure how often data is refreshed",
		position = 1
	)
	String refreshSection = "refresh";

	@ConfigSection(
		name = "Display Settings",
		description = "Configure how information is displayed",
		position = 2
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Developer",
		description = "Options for testing and debugging (no effect in normal use)",
		position = 3
	)
	String developerSection = "developer";

	// ===== REFRESH SETTINGS =====

	@ConfigItem(
		keyName = "autoRefreshEnabled",
		name = "Enable Auto-Refresh",
		description = "Automatically refresh hiscores data periodically",
		position = 1,
		section = refreshSection,
		hidden = true
	)
	default boolean autoRefreshEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "refreshIntervalMinutes",
		name = "Refresh Interval (Minutes)",
		description = "How often to automatically refresh data (minimum 5 minutes)",
		position = 2,
		section = refreshSection,
		hidden = true
	)
	default int refreshIntervalMinutes()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "dataRetentionDays",
		name = "Data Retention (Days)",
		description = "How many days of history to keep (max 180 days)",
		position = 3,
		section = refreshSection
	)
	default int dataRetentionDays()
	{
		return 180; // 6 months
	}

	// ===== DISPLAY SETTINGS =====

	@ConfigItem(
		keyName = "defaultTimeframe",
		name = "Default Timeframe",
		description = "Default timeframe for gains display",
		position = 1,
		section = displaySection
	)
	default String defaultTimeframe()
	{
		return "Today";
	}

	// ===== DEVELOPER (testing / debugging) =====

	@ConfigItem(
		keyName = "lastSelectedPlayer",
		name = "",
		description = "",
		hidden = true
	)
	default String lastSelectedPlayer()
	{
		return "";
	}

	@ConfigItem(
		keyName = "verboseDebugLogging",
		name = "Verbose debug logging",
		description = "When enabled, log extra detail at DEBUG: every game state change, login sync guard, and snapshot source. Use with Run Task 'Run RuneLite with plugin' (--debug) and filter terminal for 'Hiscores' or 'advancedxptracker'.",
		position = 1,
		section = developerSection
	)
	default boolean verboseDebugLogging()
	{
		return false;
	}
}

package com.advancedxptracker;

import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;

/**
 * Hiscores Tracker Plugin
 * Tracks player stats from OSRS Hiscores with historical gains tracking
 */
@Slf4j
@PluginDescriptor(
	name = "Hiscores Tracker",
	description = "Track player stats and gains with complete hiscores display. Multiple accounts, historical data, and daily progress tracking.",
	tags = {"hiscores", "stats", "tracking", "gains", "xp", "experience", "skills", "bosses", "clues"}
)
public class AdvancedXpTrackerPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private AdvancedXpTrackerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private Client client;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private Gson gson;

	private StatsDataManager dataManager;
	private HiscoresClient hiscoresClient;
	private HiscoresPanel panel;
	private NavigationButton navButton;
	private ScheduledExecutorService executor;
	private ScheduledExecutorService autoFetchExecutor;
	private AutoDailyFetchManager autoFetchManager;
	private volatile String loggedInUsername = null;
	private volatile int initializeTracker = 0;
	private long lastAccountHash = -1L;
	private volatile long lastStatChangeTime = 0;
	private volatile boolean statsDirty = false;

	private void verboseDebug(String format, Object... args)
	{
		if (config.verboseDebugLogging())
		{
			log.debug(format, args);
		}
	}

	@Override
	protected void startUp() throws Exception
	{
		log.info("Hiscores Tracker starting up");

		// Create executor for background tasks (file I/O, gains calculations)
		executor = Executors.newScheduledThreadPool(1);

		// Create dedicated executor for auto-fetch HTTP work (isolated from file I/O executor)
		autoFetchExecutor = Executors.newSingleThreadScheduledExecutor();

		// Initialize data manager
		log.debug("Initializing Stats Data Manager");
		dataManager = new StatsDataManager(configManager, gson);

		// Create hiscores client
		hiscoresClient = new HiscoresClient(httpClient, gson);

		// Create UI panel
		log.debug("Creating Hiscores Panel");
		panel = new HiscoresPanel(hiscoresClient, dataManager, executor, autoFetchExecutor, spriteManager, configManager);
		log.debug("Hiscores Panel created");

		autoFetchManager = new AutoDailyFetchManager(
			hiscoresClient, dataManager, autoFetchExecutor,
			(username, stats) -> SwingUtilities.invokeLater(() -> panel.onAutoFetchCompleted(username, stats))
		);

		// Start async load; refresh player list on EDT once data is ready
		dataManager.initialize(executor, () -> panel.refreshPlayerList());
		log.debug("Data Manager initialization scheduled");

		// Create and add navigation button
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		log.debug("Building navigation button");
		navButton = NavigationButton.builder()
			.tooltip("Hiscores Tracker")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.debug("Navigation button added to toolbar");
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("Hiscores Tracker shutting down");

		if (panel != null)
		{
			panel.shutDown();
		}

		if (autoFetchManager != null)
		{
			autoFetchManager.shutdown();
		}

		if (autoFetchExecutor != null)
		{
			autoFetchExecutor.shutdownNow();
		}

		if (dataManager != null)
		{
			dataManager.shutdown();
		}

		if (executor != null)
		{
			executor.shutdownNow();
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}

		loggedInUsername = null;
		lastAccountHash = -1L;
		initializeTracker = 0;
		statsDirty = false;
		lastStatChangeTime = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		verboseDebug("[GameState] {} (RuneLite/game lifecycle)", state.name());

		if (state == GameState.LOGGED_IN)
		{
			// LOGGED_IN fires on region changes too, not just actual login.
			// Only capture stats if the account actually changed.
			long currentAccountHash = client.getAccountHash();
			if (currentAccountHash != lastAccountHash)
			{
				lastAccountHash = currentAccountHash;
				if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
				{
					return;
				}
				String username = client.getLocalPlayer().getName();
				loggedInUsername = username;
				log.debug("Player logged in: '{}'", username);
				verboseDebug("[GameState] LOGGED_IN → capturing client stats (account changed)");
				captureClientStats();
				autoFetchManager.onPlayerLoggedIn(username);
			}
		}
		else if (state == GameState.LOGGING_IN || state == GameState.HOPPING)
		{
			// Set initialization guard -- skip StatChanged events for 2 game ticks
			// to avoid processing the login sync burst
			initializeTracker = 2;
			statsDirty = false;
			verboseDebug("[GameState] {} → set init guard (2 ticks, skip StatChanged)", state.name());
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			if (loggedInUsername != null)
			{
				log.debug("Player '{}' logged out", loggedInUsername);
				verboseDebug("[GameState] LOGIN_SCREEN → cleared logged-in user");
				autoFetchManager.onPlayerLoggedOut();
				loggedInUsername = null;
				lastAccountHash = -1L;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (initializeTracker > 0)
		{
			int before = initializeTracker;
			initializeTracker--;
			if (before > 0)
			{
				verboseDebug("[InitGuard] ticks left={} (StatChanged will be {} accepted)", initializeTracker, initializeTracker == 0 ? "now" : "ignored until 0");
			}
			return;
		}

		// Debounce: capture stats after 5 seconds of no XP changes
		if (statsDirty && System.currentTimeMillis() - lastStatChangeTime >= 5000)
		{
			statsDirty = false;
			captureClientStats();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		if (initializeTracker > 0)
		{
			verboseDebug("[StatChanged] skipped (login sync guard, ticks left={}), skill={}", initializeTracker, statChanged.getSkill());
			return;
		}

		if (loggedInUsername != null && client.getGameState() == GameState.LOGGED_IN)
		{
			log.debug("Stat changed for '{}': {}", loggedInUsername, statChanged.getSkill());
			lastStatChangeTime = System.currentTimeMillis();
			statsDirty = true;
		}
	}

	private void captureClientStats()
	{
		if (loggedInUsername == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// Phase 1: Read client API (MUST be on game thread — fast, ~50 memory reads)
		final String username = loggedInUsername;
		final long timestamp = System.currentTimeMillis();
		final int[] levels = new int[Skill.values().length];
		final long[] xps = new long[Skill.values().length];

		int totalLevel = 0;
		long totalXp = 0;
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				int idx = skill.ordinal();
				levels[idx] = client.getRealSkillLevel(skill);
				xps[idx] = client.getSkillExperience(skill);
				totalLevel += levels[idx];
				totalXp += xps[idx];
			}
		}
		final int finalTotalLevel = totalLevel;
		final long finalTotalXp = totalXp;

		log.debug("Captured client stats for '{}', dispatching to executor", username);

		// Phase 2: Build snapshot + persist + notify (on background executor)
		executor.submit(() -> {
			try
			{
				PlayerStats stats = new PlayerStats(username, timestamp, "client");
				stats.setSkill("overall", -1, finalTotalLevel, finalTotalXp);

				for (Skill skill : Skill.values())
				{
					if (skill != Skill.OVERALL)
					{
						String skillName = skill.getName().toLowerCase();
						stats.setSkill(skillName, -1, levels[skill.ordinal()], xps[skill.ordinal()]);
					}
				}

				dataManager.saveSnapshot(stats, "client");
				log.debug("Saved client snapshot for '{}'", username);

				// Notify panel on EDT
				SwingUtilities.invokeLater(() -> panel.onClientStatsUpdated(username));
			}
			catch (Exception e)
			{
				log.error("Failed to process client stats for '{}'", username, e);
			}
		});
	}

	@Provides
	AdvancedXpTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AdvancedXpTrackerConfig.class);
	}
}

package com.advancedxptracker;

import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Ensures every tracked player has at least one Hiscores API snapshot per calendar day.
 * Runs fetch cycles on login and hourly, using the shared executor for all work.
 */
@Slf4j
public class AutoDailyFetchManager
{
	@FunctionalInterface
	public interface AutoFetchListener
	{
		void onPlayerFetched(String username, PlayerStats stats);
	}

	private static final long INTER_PLAYER_DELAY_SECONDS = 10;
	private static final long HOURLY_PERIOD_HOURS = 1;

	private final HiscoresClient hiscoresClient;
	private final StatsDataManager dataManager;
	private final ScheduledExecutorService executor;
	private final AutoFetchListener listener;

	/** Guards hourly timer; only one should run at a time. */
	private ScheduledFuture<?> hourlyTimer;

	/** The currently-scheduled next step of an in-flight fetch cycle. */
	private ScheduledFuture<?> pendingFetchStep;

	/** Set to true when a fetch cycle should be aborted (logout or shutdown). */
	private volatile boolean stopped = false;

	public AutoDailyFetchManager(
		HiscoresClient hiscoresClient,
		StatsDataManager dataManager,
		ScheduledExecutorService executor,
		AutoFetchListener listener)
	{
		this.hiscoresClient = hiscoresClient;
		this.dataManager = dataManager;
		this.executor = executor;
		this.listener = listener;
	}

	/**
	 * Called when a player logs in. Cancels any running fetch cycle, schedules an
	 * immediate one with the logged-in player prioritised, and starts the hourly
	 * timer if it is not already running.
	 */
	public synchronized void onPlayerLoggedIn(String username)
	{
		log.debug("Auto-daily fetch: player logged in ({})", username);

		stopped = false;
		cancelPendingFetchStep();
		scheduleImmediateFetchCycle(username);

		if (hourlyTimer == null || hourlyTimer.isCancelled() || hourlyTimer.isDone())
		{
			try
			{
				hourlyTimer = executor.scheduleAtFixedRate(
					() -> triggerFetchCycle(null),
					HOURLY_PERIOD_HOURS,
					HOURLY_PERIOD_HOURS,
					TimeUnit.HOURS);
				log.debug("Auto-daily fetch: hourly timer started");
			}
			catch (java.util.concurrent.RejectedExecutionException e)
			{
				log.debug("Auto-daily fetch: executor shut down, cannot start hourly timer");
			}
		}
	}

	/**
	 * Called when the player reaches the login screen. Cancels the hourly timer
	 * and any in-flight fetch step.
	 */
	public synchronized void onPlayerLoggedOut()
	{
		log.debug("Auto-daily fetch: player logged out");
		stopped = true;
		cancelHourlyTimer();
		cancelPendingFetchStep();
	}

	/**
	 * Cancels all timers immediately. Called from Plugin.shutDown().
	 */
	public synchronized void shutdown()
	{
		log.debug("Auto-daily fetch: shutting down");
		stopped = true;
		cancelHourlyTimer();
		cancelPendingFetchStep();
	}

	// -----------------------------------------------------------------
	// Internal helpers
	// -----------------------------------------------------------------

	private void scheduleImmediateFetchCycle(String priorityUsername)
	{
		try
		{
			pendingFetchStep = executor.schedule(
				() -> triggerFetchCycle(priorityUsername),
				0,
				TimeUnit.SECONDS);
		}
		catch (java.util.concurrent.RejectedExecutionException e)
		{
			log.debug("Auto-daily fetch: executor shut down, cannot schedule immediate fetch cycle");
		}
	}

	private void cancelHourlyTimer()
	{
		if (hourlyTimer != null)
		{
			hourlyTimer.cancel(false);
			hourlyTimer = null;
			log.debug("Auto-daily fetch: hourly timer cancelled");
		}
	}

	private void cancelPendingFetchStep()
	{
		if (pendingFetchStep != null)
		{
			pendingFetchStep.cancel(false);
			pendingFetchStep = null;
			log.debug("Auto-daily fetch: pending fetch step cancelled");
		}
	}

	// -----------------------------------------------------------------
	// Fetch cycle
	// -----------------------------------------------------------------

	/**
	 * Build the list of stale players and begin fetching them sequentially.
	 *
	 * @param priorityUsername player to place first in the queue, or null for alphabetical order only
	 */
	void triggerFetchCycle(String priorityUsername)
	{
		if (!dataManager.isInitialized())
		{
			log.debug("Auto-daily fetch: data manager not yet initialized, skipping cycle");
			return;
		}

		List<String> tracked = dataManager.getTrackedPlayers();
		if (tracked.isEmpty())
		{
			log.debug("Auto-daily fetch: no tracked players, skipping cycle");
			return;
		}

		LocalDate today = LocalDate.now();
		List<String> stale = new ArrayList<>();

		for (String player : tracked)
		{
			if (isStale(player, today))
			{
				stale.add(player);
			}
		}

		if (stale.isEmpty())
		{
			log.debug("Auto-daily fetch: all {} tracked players already have a snapshot for today", tracked.size());
			return;
		}

		// Sort: priority player first, then alphabetical
		final String priority = priorityUsername != null ? priorityUsername.toLowerCase() : null;
		stale.sort(Comparator.<String, Integer>comparing(
				p -> priority != null && p.equalsIgnoreCase(priority) ? 0 : 1)
			.thenComparing(String.CASE_INSENSITIVE_ORDER));

		log.debug("Auto-daily fetch: {} of {} tracked players are stale, starting fetch cycle",
			stale.size(), tracked.size());

		fetchNext(stale, 0, stale.size());
	}

	/**
	 * Returns true when the player has no Hiscores API snapshot dated today.
	 */
	private boolean isStale(String username, LocalDate today)
	{
		PlayerStats latest = dataManager.getLatestHiscoresSnapshot(username);
		if (latest == null)
		{
			return true;
		}
		LocalDate snapshotDate = Instant.ofEpochMilli(latest.getTimestamp())
			.atZone(ZoneId.systemDefault())
			.toLocalDate();
		return !snapshotDate.equals(today);
	}

	/**
	 * Fetch the player at {@code index} in {@code queue}, then schedule the next
	 * fetch after a 10-second delay (or log the summary when the queue is exhausted).
	 */
	private void fetchNext(List<String> queue, int index, int totalStale)
	{
		if (index >= queue.size())
		{
			log.info("Auto-fetch complete: updated {} of {} tracked players",
				totalStale, dataManager.getTrackedPlayers().size());
			return;
		}

		String username = queue.get(index);
		log.debug("Auto-daily fetch: fetching '{}' ({}/{})", username, index + 1, queue.size());

		try
		{
			AccountType accountType = dataManager.loadAccountType(username);
			PlayerStats stats = hiscoresClient.fetchPlayerStats(username, accountType);
			dataManager.saveSnapshot(stats, "hiscores_api");
			listener.onPlayerFetched(username, stats);
			log.debug("Auto-daily fetch: successfully fetched '{}'", username);
		}
		catch (PlayerNotFoundException e)
		{
			log.warn("Auto-daily fetch: player '{}' not found (404), skipping", username);
		}
		catch (IOException e)
		{
			log.warn("Auto-daily fetch: failed to fetch '{}': {}", username, e.getMessage());
		}

		// Schedule next fetch step — the guard at the top of fetchNext handles
		// the completion summary when index + 1 reaches queue.size().
		long delay = (index + 1 < queue.size()) ? INTER_PLAYER_DELAY_SECONDS : 0;
		synchronized (this)
		{
			if (stopped) return;
			try
			{
				pendingFetchStep = executor.schedule(
					() -> fetchNext(queue, index + 1, totalStale),
					delay,
					TimeUnit.SECONDS);
			}
			catch (java.util.concurrent.RejectedExecutionException e)
			{
				log.debug("Auto-daily fetch: executor shut down, cannot schedule next fetch step");
			}
		}
	}
}

package com.advancedxptracker;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Client for fetching player data from OSRS Hiscores API
 */
@Slf4j
public class HiscoresClient
{
	private static final Map<String, String> NAME_TO_KEY_MAP = createNameToKeyMapping();

	private static final long CACHE_TTL_MS = 60_000;

	private final OkHttpClient httpClient;
	private final Gson gson;

	private final Map<String, CachedResult> responseCache = new ConcurrentHashMap<>();

	private static class CachedResult
	{
		final PlayerStats stats;
		final long timestamp;

		CachedResult(PlayerStats stats)
		{
			this.stats = stats;
			this.timestamp = System.currentTimeMillis();
		}

		boolean isExpired()
		{
			return System.currentTimeMillis() - timestamp > CACHE_TTL_MS;
		}
	}

	public HiscoresClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * Fetch hiscores data for a player
	 * @param username Player name
	 * @param accountType Account type (Normal, Ironman, etc.)
	 * @return PlayerStats object with all hiscores data
	 */
	public PlayerStats fetchPlayerStats(String username, AccountType accountType) throws IOException
	{
		log.debug("Fetching hiscores for '{}' ({})", username, accountType.getDisplayName());

		String cacheKey = username.toLowerCase() + ":" + accountType.name();
		CachedResult cached = responseCache.get(cacheKey);
		if (cached != null && !cached.isExpired())
		{
			log.debug("Returning cached hiscores for '{}'", username);
			return cached.stats;
		}

		String encodedUsername = URLEncoder.encode(username, StandardCharsets.UTF_8);
		String url = accountType.getApiUrl() + encodedUsername;
		log.debug("API URL: {}", url);

		Request request = new Request.Builder()
			.url(url)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				int code = response.code();
				if (code == 404)
				{
					throw new PlayerNotFoundException(username);
				}
				else if (code == 429)
				{
					throw new IOException("Hiscores API rate limit reached. Please wait a moment and try again.");
				}
				else
				{
					throw new IOException("Hiscores API error (HTTP " + code + "). The service may be temporarily unavailable.");
				}
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Empty response from Hiscores API");
			}
			String jsonData = body.string();
			log.debug("API response received, body length: {} characters", jsonData.length());

			PlayerStats result = parseHiscoresJson(username, jsonData);
			responseCache.put(cacheKey, new CachedResult(result));
			log.debug("Finished fetching for '{}'", username);
			return result;
		}
	}

	/**
	 * Parse the hiscores JSON response into PlayerStats using name-based mapping
	 */
	private PlayerStats parseHiscoresJson(String username, String jsonData)
	{
		log.debug("Parsing hiscores JSON data for username: '{}'", username);

		HiscoresResponse response;
		try
		{
			response = gson.fromJson(jsonData, HiscoresResponse.class);
		}
		catch (Exception e)
		{
			log.error("Failed to parse JSON response", e);
			throw new RuntimeException("Failed to parse hiscores JSON", e);
		}

		if (response == null)
		{
			log.error("Parsed response is null");
			throw new RuntimeException("Hiscores response is null");
		}

		PlayerStats stats = new PlayerStats(username, System.currentTimeMillis(), "hiscores_api");

		// Parse skills from JSON
		if (response.skills != null)
		{
			log.debug("Parsing {} skills from JSON", response.skills.length);
			int skillsParsed = 0;
			for (HiscoresResponse.SkillEntry skill : response.skills)
			{
				String key = NAME_TO_KEY_MAP.get(skill.name);
				if (key != null)
				{
					stats.setSkill(key, skill.rank, skill.level, skill.xp);
					skillsParsed++;
					log.debug("  Skill '{}' → '{}': level={}, xp={}", skill.name, key, skill.level, skill.xp);
				}
				else
				{
					log.debug("Unknown skill in hiscore: {}", skill.name);
				}
			}
			log.debug("Parsed {} skills", skillsParsed);
		}

		// Parse activities and bosses from JSON using name-based mapping
		if (response.activities != null)
		{
			log.debug("Parsing {} activities/bosses from JSON", response.activities.length);
			int activitiesParsed = 0;
			int activitiesWithScores = 0;

			for (HiscoresResponse.ActivityEntry activity : response.activities)
			{
				String key = NAME_TO_KEY_MAP.get(activity.name);
				if (key != null)
				{
					stats.setActivity(key, activity.rank, (int) activity.score);
					activitiesParsed++;

					if (activity.score > 0)
					{
						activitiesWithScores++;
						log.debug("Activity '{}' -> '{}': rank={}, score={}", activity.name, key, activity.rank, activity.score);
					}
				}
				else
				{
					log.debug("Unknown activity in hiscore: {}", activity.name);
				}
			}

			log.debug("Parsed {} activities/bosses total, {} have non-zero scores", activitiesParsed, activitiesWithScores);
		}

		log.debug("Successfully parsed hiscores for '{}'", username);
		return stats;
	}

