package com.advancedxptracker;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.util.HashMap;
import java.util.Map;

/**
 * Represents a player's complete hiscores data at a point in time
 */
@Slf4j
@Getter
public class PlayerStats
{
	private final String username;
	private final long timestamp;
	private final Map<String, SkillData> skills;
	private final Map<String, ActivityData> activities;
	private final String source;

	public PlayerStats(String username, long timestamp, String source)
	{
		this.username = username;
		this.timestamp = timestamp;
		this.source = source;
		this.skills = new HashMap<>();
		this.activities = new HashMap<>();
	}

	public PlayerStats(String username, long timestamp)
	{
		this(username, timestamp, null);
	}

	public void setSkill(String name, int rank, int level, long xp)
	{
		skills.put(name, new SkillData(rank, level, xp));
	}

	public void setActivity(String name, int rank, int score)
	{
		activities.put(name, new ActivityData(rank, score));
	}

	/**
	 * Get total XP across all skills via the overall skill entry.
	 * Used for snapshot coalescing — skip saving when XP unchanged.
	 */
	public long getTotalXp()
	{
		SkillData overall = skills.get("overall");
		return overall != null ? overall.getXp() : 0;
	}

	/**
	 * Calculate gains compared to an older snapshot
	 */
	public PlayerGains calculateGains(PlayerStats older)
	{
		if (older == null)
		{
			return new PlayerGains(this, null);
		}

		PlayerGains gains = new PlayerGains(this, older);

		// Calculate skill XP gains
		for (Map.Entry<String, SkillData> entry : skills.entrySet())
		{
			String skillName = entry.getKey();
			SkillData current = entry.getValue();
			SkillData old = older.skills.get(skillName);

			if (old != null)
			{
				long xpGain = current.xp - old.xp;
				int levelGain = current.level - old.level;
				gains.addSkillGain(skillName, xpGain, levelGain);
			}
		}

		// Calculate activity score gains
		for (Map.Entry<String, ActivityData> entry : activities.entrySet())
		{
			String activityName = entry.getKey();
			ActivityData current = entry.getValue();
			ActivityData old = older.activities.get(activityName);

			if (old != null)
			{
				int scoreGain = current.score - old.score;
				gains.addActivityGain(activityName, scoreGain);
			}
		}

		return gains;
	}

	/**
	 * Data class for skill information
	 */
	@Getter
	public static class SkillData
	{
		private final int rank;
		private final int level;
		private final long xp;

		public SkillData(int rank, int level, long xp)
		{
			this.rank = rank;
			this.level = level;
			this.xp = xp;
		}
	}

	/**
	 * Data class for activity/boss information
	 */
	@Getter
	public static class ActivityData
	{
		private final int rank;
		private final int score;

		public ActivityData(int rank, int score)
		{
			this.rank = rank;
			this.score = score;
		}
	}
}

package com.advancedxptracker;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.game.SpriteManager;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;

/**
 * Utility to extract and save sprite images for verification
 */
@Slf4j
public class SpriteViewer
{
	private final SpriteManager spriteManager;

	public SpriteViewer(SpriteManager spriteManager)
	{
		this.spriteManager = spriteManager;
	}

	/**
	 * Extract a sprite and save it as PNG for verification
	 */
	public void saveSpriteImage(int spriteId, String filename)
	{
		log.debug("Attempting to load sprite ID: {}", spriteId);

		spriteManager.getSpriteAsync(spriteId, 0, (sprite) ->
		{
			if (sprite != null)
			{
				try
				{
					File outputDir = new File(RuneLite.RUNELITE_DIR, "sprite-debug");
					outputDir.mkdirs();

					File outputFile = new File(outputDir, filename);
					ImageIO.write(sprite, "PNG", outputFile);

					log.debug("Sprite {} saved to: {}", spriteId, outputFile.getAbsolutePath());
					log.debug("Sprite dimensions: {}x{}", sprite.getWidth(), sprite.getHeight());
				}
				catch (IOException e)
				{
					log.error("Failed to save sprite {}: {}", spriteId, e.getMessage());
				}
			}
			else
			{
				log.warn("Sprite {} returned null", spriteId);
			}
		});
	}

	/**
	 * Save all three sprites we're trying to identify
	 */
	public void saveTestSprites(int sailingId, int doomId, int shellbaneId)
	{
		log.debug("Sprite verification start, testing IDs: sailing={}, doom={}, shellbane={}", sailingId, doomId, shellbaneId);

		saveSpriteImage(sailingId, String.format("sailing_%d.png", sailingId));
		saveSpriteImage(doomId, String.format("doom_%d.png", doomId));
		saveSpriteImage(shellbaneId, String.format("shellbane_%d.png", shellbaneId));

		log.debug("Sprite verification end");
	}

	/**
	 * Test a range of sprite IDs to find the correct ones
	 */
	public void testSpriteRange(int startId, int endId, String prefix)
	{
		log.debug("Testing sprite range {}-{} with prefix '{}'", startId, endId, prefix);

		for (int i = startId; i <= endId; i++)
		{
			final int spriteId = i;
			saveSpriteImage(spriteId, String.format("%s_%d.png", prefix, spriteId));
		}
	}
}

